import json, os
here = os.path.dirname(os.path.abspath(__file__))
sec = json.load(open(os.path.join(here, '..', 'sectors.json')))

def legsets(key, p=None, nmax=None):
    blk = sec['arity1'] if '(1)' in key else sec['arity2']
    out = []
    for s in blk[key]['sectors']:
        if p is not None and s['p'] != p: continue
        if nmax is not None and s['n'] > nmax: continue
        out.append({'legs': s['legs'], 'n': s['n'], 'p': s['p'], 'D': s['D']})
    return out

